'use strict';
const TrainingContent = (() => {
  const escape = value => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
  const code = value => `<pre><code>${escape(value)}</code></pre>`;
  const inline = value => `<code>${escape(value)}</code>`;
  const number = (key,label,answer) => ({key,label,kind:'number',answer,hint:'Geben Sie das Ergebnis als Dezimalzahl ein.'});
  const java = (key,label,answer) => ({key,label,kind:'java',answer});
  const choice = (key,label,answer,options) => ({key,label,kind:'choice',answer,options});
  const text = (key,label,answer) => ({key,label,kind:'text',answer});
  const q = (title,prompt,fields,hint,solution) => ({title,prompt,fields,hint,solution});
  const experiment = (title,body) => `<section class="experiment"><h3>${title}</h3>${body}</section>`;
  const cell = `class Cell {
    private boolean alive;

    Cell(boolean alive) {
        this.alive = alive;
    }

    boolean getAlive() {
        return alive;
    }

    void setAlive(boolean alive) {
        this.alive = alive;
    }

    void change() {
        setAlive(!getAlive());
    }
}`;
  const cellContext = '<p>Für diese Aufgabe gilt: Eine neue Cell speichert den boolean-Konstruktorparameter im eigenen Attribut alive. getAlive() liefert diesen Wert, setAlive(boolean alive) ersetzt ihn und change() kehrt ihn um. Der folgende Code wird unabhängig von allen anderen Aufgaben ausgeführt.</p>';
  const doublingCode = (start, count) => code(`int zahl = ${start};\nint anzahl = ${count};\nwhile (anzahl > 0) {\n    zahl = zahl * 2;\n    anzahl = anzahl - 1;\n}\nSystem.out.println(zahl);`);
  const truth = [['true','true'],['false','false']];
  const kinds = [['primitive','primitiv'],['reference','komplex / Referenztyp']];
  const pap = `<svg class="pap" viewBox="0 0 580 560" role="img" aria-label="Programmablaufplan: Eingabe, Schleifenbedingung, Verdoppeln, Zählvariable verringern, Rücksprung zur Bedingung und Ausgabe beim Verlassen der Schleife"><defs><marker id="pap-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M 0 0 L 10 5 L 0 10 Z" fill="#44776c"/></marker></defs><ellipse class="node" data-node="start" cx="280" cy="28" rx="65" ry="21"/><text x="280" y="33" text-anchor="middle">Start</text><path class="flow" d="M280 49 V68"/><path class="node" data-node="input" d="M195 70 H385 L365 112 H175 Z"/><text x="280" y="96" text-anchor="middle">Eingabe: zahl, anzahl</text><path class="flow" d="M280 113 V133"/><path class="node" data-node="condition" d="M280 135 L395 185 L280 235 L165 185 Z"/><text id="pap-condition" x="280" y="190" text-anchor="middle">anzahl &gt; 0</text><path class="flow" d="M280 235 V268"/><text x="291" y="253">ja</text><rect class="node" data-node="double" x="185" y="270" width="190" height="45"/><text id="pap-double" x="280" y="298" text-anchor="middle">zahl = zahl * 2;</text><path class="flow" d="M280 315 V338"/><rect class="node" data-node="decrement" x="185" y="340" width="190" height="45"/><text id="pap-decrement" x="280" y="368" text-anchor="middle">anzahl = anzahl - 1;</text><path class="flow" d="M375 362 H485 V185 H398"/><path class="flow" d="M165 185 H85 V450 H175"/><text x="113" y="175">nein</text><path class="node" data-node="output" d="M195 428 H385 L365 472 H175 Z"/><text x="280" y="456" text-anchor="middle">Ausgabe: zahl</text><path class="flow" d="M280 472 V505"/><ellipse class="node" data-node="end" cx="280" cy="529" rx="65" ry="21"/><text x="280" y="534" text-anchor="middle">Ende</text></svg>`;
  const stations = [
  {
    id:'binaer', name:'Binärzahlen', time:'15–20', title:'Dieselben Bits, unterschiedliche Bedeutungen.',
    intro:'Lesen Sie Stellenwerte, wandeln Sie Zahlen um und trennen Sie das gespeicherte Muster von seiner Interpretation.',
    lesson:`<h3>Jede Stelle zählt doppelt.</h3><p>Ein Bit hat zwei Zustände: 0 oder 1. Von rechts nach links haben acht Bits die Stellenwerte 1, 2, 4, 8, 16, 32, 64 und 128. Addieren Sie die Stellenwerte, deren Bit 1 ist.</p><p class="rule">101101₂ = 32 + 8 + 4 + 1 = 45₁₀<br>37₁₀ = 32 + 4 + 1 = 00100101₂</p><p>Führende Nullen verändern den Zahlenwert nicht. In diesen Aufgaben nutzen wir acht Bits für die Zahlen von 0 bis 255. Das sind 256 verschiedene Bitmuster.</p>${code('int zahl = 0b00100101; // 37 als Binärliteral\nint doppelt = zahl * 2; // 74')}
    ${experiment('Bitlabor: Zahl, Zeichen und LEDs', '<p>Schalten Sie die Bits um. Das Programm entscheidet, ob das Muster als Dezimalzahl, als ASCII-Zeichen oder als Schaltzustände gelesen wird.</p><div id="bit-lab" class="bit-grid"></div><div id="bit-readout" class="readout" aria-live="polite"></div><div id="leds" class="leds" aria-label="Acht LEDs, von links nummeriert"></div>')}`,
    reflection:'Warum kann das Muster 01000010 sowohl 66 als auch B oder zwei leuchtende LEDs bedeuten? Erklären Sie die Rolle des Programms bzw. Datentyps.',
    questions:[
      q('Stellenwerte lesen','<p>Wandeln Sie <strong>101101₂</strong> in eine Dezimalzahl um.</p>',[number('decimal','Welche Dezimalzahl entspricht der Binärzahl 101101₂?',45)],'Notieren Sie unter jeder 1 den zugehörigen Stellenwert.','32 + 8 + 4 + 1 = 45.'),
      q('Acht Stellen schreiben','<p>Stellen Sie die Dezimalzahl <strong>37₁₀</strong> als Binärzahl mit genau acht Stellen dar.</p>',[text('binary','Wie lautet die Binärzahl für 37₁₀ mit genau acht Stellen?','00100101')],'Beginnen Sie mit der größten Zweierpotenz, die noch in 37 passt.','37 = 32 + 4 + 1. Die Stellen für 32, 4 und 1 sind gesetzt: 00100101.'),
      q('Ein Byte interpretieren','<p>Im Speicher steht die Binärzahl <strong>01000010₂</strong>. Deuten Sie die acht Bits als Zahl, ASCII-Zeichen und LED-Zustände. Die LEDs sind von links mit 1 bis 8 nummeriert; eine 1 bedeutet „leuchtet“. ASCII ordnet der Dezimalzahl 65 das Zeichen A und der Dezimalzahl 66 das Zeichen B zu.</p>',[number('value','Welche Dezimalzahl stellt das Bitmuster 01000010₂ dar?',66),text('character','Welches ASCII-Zeichen gehört zu diesem Bitmuster?','B'),choice('leds','Welche beiden LEDs leuchten, wenn jede 1 im Bitmuster eine eingeschaltete LED bedeutet?','2,7',[['1,6','1 und 6'],['2,7','2 und 7'],['2,6','2 und 6']])],'Die zweite und die siebte Stelle von links enthalten eine 1.','64 + 2 = 66. ASCII ordnet 66 dem Zeichen B zu. Die LEDs 2 und 7 leuchten.'),
      q('Acht Bits ausschöpfen','<p>Acht Bits werden für nicht negative ganze Zahlen verwendet: 00000000₂ steht für 0₁₀. Wie viele verschiedene Bitmuster gibt es, und welche ist die größte darstellbare Zahl? Geben Sie beide Ergebnisse als Dezimalzahlen ein.</p>',[number('patterns','Wie viele verschiedene Bitmuster lassen sich mit acht Bits bilden?',256),number('max','Welche ist die größte nicht negative ganze Zahl, die Sie mit acht Bits darstellen können?',255)],'Mit jeder zusätzlichen Stelle verdoppelt sich die Anzahl der Muster. Die Zahl 0 wird mitgezählt.','2⁸ = 256 Bitmuster. Die größte Zahl ist 11111111₂ = 128 + 64 + 32 + 16 + 8 + 4 + 2 + 1 = 255₁₀.')]
  },
  {
    id:'algorithmen', name:'Algorithmen mit Bits', time:'20–25', title:'Rechenwege Schritt für Schritt verfolgen.',
    intro:'Eine Umrechnung und eine Schleife werden nachvollziehbar, wenn Sie nach jedem Schritt den Zustand der Variablen festhalten.',
    lesson:`<h3>Dezimal → Binär mit Division durch 2</h3><p>Teilen Sie die Zahl wiederholt ganzzahlig durch 2. Notieren Sie jeweils den Rest. Lesen Sie die Reste zuletzt von unten nach oben. Die Zahl 0 benötigt die gesonderte Ausgabe "0".</p>${code('int rest = zahl % 2;\nzahl = zahl / 2; // Ganzzahldivision bei int')}
    ${experiment('Umrechnung ausführen', '<label for="division-value">Startzahl als Dezimalzahl (0–255)</label><input id="division-value" type="number" min="0" max="255" step="1" value="37"><div class="controls"><button id="division-start" type="button">Neu beginnen</button><button id="division-step" type="button" class="secondary">Nächste Division</button></div><div id="division-trace" aria-live="polite"></div>')}
    <details><summary>Die vollständige Umrechnung als Java-Code</summary><p>Für nicht negative ganze Zahlen werden die Reste jeweils vorne an die Zeichenkette angefügt. Dadurch steht der zuletzt berechnete Rest links.</p>${code('int zahl = 37;\nString binaer = "";\nif (zahl == 0) {\n    binaer = "0";\n}\nwhile (zahl > 0) {\n    int rest = zahl % 2;\n    binaer = rest + binaer;\n    zahl = zahl / 2;\n}\nSystem.out.println(binaer); // 100101')}</details>
    <h3>Verdoppeln als Schleife</h3>${code('int zahl = 5;\nint anzahl = 3;\nwhile (anzahl > 0) {\n    zahl = zahl * 2;\n    anzahl = anzahl - 1;\n}\nSystem.out.println(zahl);')}
    <p>Nach jedem Durchlauf ist die Zählvariable um 1 kleiner. Die Bedingung wird <em>vor</em> jedem Durchlauf geprüft. Eine Linksverschiebung um eine Stelle multipliziert einen nicht negativen Binärwert mit 2, solange kein relevantes Bit verloren geht.</p>${code('int zahl = 5;\nint doppelt = zahl << 1; // 00000101 → 00001010, also 10')}
    ${experiment('Verdopplung beobachten', '<label for="double-value">Startzahl als Dezimalzahl (1–255)</label><input id="double-value" type="number" min="1" max="255" step="1" value="5"><label for="double-count">Anzahl Verdopplungen als Dezimalzahl (0–8)</label><input id="double-count" type="number" min="0" max="8" step="1" value="3"><div class="controls"><button id="double-start" type="button">Neu beginnen</button><button id="double-step" type="button" class="secondary">Ein Schleifendurchlauf</button></div><div id="double-trace" aria-live="polite"></div><p class="small">Alle Eingaben erfolgen als Dezimalzahlen. Die Tabelle zeigt den Wert von zahl zusätzlich als Binärzahl. Bei Ergebnissen über 255 sind mehr als acht Binärstellen erforderlich.</p>')}`,
    reflection:'Warum muss anzahl in jedem Durchlauf verringert werden? Begründen Sie mit den Stellenwerten, weshalb eine Linksverschiebung verdoppelt.',
    questions:[
      q('Reste richtig lesen','<p>Bei der wiederholten ganzzahligen Division der Dezimalzahl 13₁₀ durch 2 entstehen nacheinander die Reste 1, 0, 1, 1. Welche Binärzahl entsteht ohne führende Nullen?</p>',[text('binary','Welche Binärzahl ergibt sich, wenn Sie die Reste in der richtigen Reihenfolge lesen? Geben Sie sie ohne führende Nullen ein.','1101')],'Lesen Sie den zuletzt erhaltenen Rest zuerst.','13 = 6 · 2 + 1; 6 = 3 · 2 + 0; 3 = 1 · 2 + 1; 1 = 0 · 2 + 1. Von unten nach oben: 1101.'),
      q('Die Schleife protokollieren','<p>Führen Sie den folgenden Java-Code gedanklich aus. Notieren Sie die Werte direkt nach den angegebenen vollständigen Schleifendurchläufen. Geben Sie alle Werte als Dezimalzahlen ein.</p>'+doublingCode(5,3),[number('first','Welchen Wert hat die Variable zahl nach dem ersten vollständigen Schleifendurchlauf?',10),number('second','Welchen Wert hat die Variable zahl nach dem zweiten vollständigen Schleifendurchlauf?',20),number('third','Welchen Wert hat die Variable zahl nach dem dritten vollständigen Schleifendurchlauf?',40),number('count','Welchen Wert hat die Zählvariable anzahl nach dem dritten vollständigen Schleifendurchlauf?',0)],'Führen Sie beide Anweisungen pro Durchlauf aus.','(5, 3) → (10, 2) → (20, 1) → (40, 0). Danach ist anzahl > 0 falsch.'),
      q('Ausgabe und Startbedingung','<p><strong>Teil 1:</strong> Wandeln Sie die Dezimalzahl 40₁₀ in eine Binärzahl mit genau acht Stellen um.</p><p><strong>Teil 2:</strong> Untersuchen Sie unabhängig davon den folgenden Java-Code. Wie oft wird der Schleifenrumpf ausgeführt? Geben Sie diese Anzahl als Dezimalzahl ein.</p>'+doublingCode(5,0),[text('bits','Wie stellen Sie die Dezimalzahl 40₁₀ als Binärzahl mit genau acht Stellen dar?','00101000'),number('runs','Wie oft wird der Schleifenrumpf im angegebenen Code ausgeführt, wenn anzahl zu Beginn 0 ist?',0)],'40 ist die Summe aus 32 und 8. Eine while-Schleife prüft vor dem ersten Durchlauf.','40 = 32 + 8 = 00101000₂. Bei anzahl = 0 ist die Bedingung sofort falsch: kein Durchlauf.'),
      q('Die 8-Bit-Grenze','<p>Starten Sie mit der Dezimalzahl <strong>5₁₀</strong> und verdoppeln Sie sie wiederholt. Die Ergebnisse dürfen höchstens 255₁₀ betragen, damit sie mit acht Bits darstellbar bleiben. Wie viele Verdopplungen sind möglich, und welcher Wert wird dabei zuletzt erreicht? Geben Sie beide Ergebnisse als Dezimalzahlen ein.</p>',[number('times','Wie oft können Sie die Startzahl 5 verdoppeln, ohne die Grenze 255 zu überschreiten?',5),number('last','Welchen Wert hat die Zahl nach der letzten noch erlaubten Verdopplung?',160)],'Verdoppeln Sie weiter, bis Sie die Grenze 255 überschreiten.','5 → 10 → 20 → 40 → 80 → 160 passt noch. Erst die sechste Verdopplung liefert 320. Jede Linksverschiebung verdoppelt die Stellenwerte.')]
  },
  {
    id:'pap', name:'Programmablaufpläne', time:'15–20', title:'Ein Ablauf wird zum Plan.',
    intro:'Erkennen Sie die Elemente eines PAP und verbinden Sie Entscheidungen, Verarbeitung und Rücksprünge zu einem Algorithmus.',
    lesson:`<h3>Unser Beispiel: eine Zahl mehrfach verdoppeln</h3>
    <p>Ein Programm soll eine eingegebene Zahl so oft verdoppeln, wie es eine zweite Eingabe vorgibt. Dafür verwendet es zwei int-Variablen: <strong>zahl</strong> enthält den aktuellen Zahlenwert; die <strong>Zählvariable anzahl</strong> enthält die noch auszuführenden Verdopplungen. Beide Eingaben sind nicht negative ganze Zahlen und werden als Dezimalzahlen eingegeben.</p>
    <ol><li>Lesen Sie die Startwerte für zahl und anzahl ein.</li><li>Prüfen Sie vor jedem Durchlauf, ob anzahl größer als 0 ist.</li><li>Wenn ja: Verdoppeln Sie zahl und verringern Sie anzahl um 1. Kehren Sie anschließend zur Prüfung in Schritt 2 zurück.</li><li>Wenn nein: Geben Sie den aktuellen Wert von zahl als Dezimalzahl aus und beenden Sie das Programm.</li></ol>
    <p>Ist anzahl schon zu Beginn 0, wird nicht verdoppelt: Das Programm gibt die unveränderte Startzahl aus.</p>
    <div class="table-wrap"><table><caption>Beispiel: Startzahl 5, drei Verdopplungen – alle Werte als Dezimalzahlen</caption><thead><tr><th>Zeitpunkt</th><th>zahl</th><th>anzahl (Zählvariable)</th></tr></thead><tbody><tr><td>Start</td><td>5</td><td>3</td></tr><tr><td>Nach Durchlauf 1</td><td>10</td><td>2</td></tr><tr><td>Nach Durchlauf 2</td><td>20</td><td>1</td></tr><tr><td>Nach Durchlauf 3</td><td>40</td><td>0</td></tr></tbody></table></div>
    <p>Nun ist anzahl nicht mehr größer als 0. Die Ausgabe ist die Dezimalzahl <strong>40</strong>. Diesen Ablauf stellen Sie im folgenden Programmablaufplan (PAP) dar.</p>
    <h3>Vier Grundelemente</h3><div class="pap-symbols"><div><svg viewBox="0 0 140 70" aria-hidden="true"><ellipse cx="70" cy="35" rx="60" ry="25" fill="#eef6f3" stroke="#44776c" stroke-width="2"/></svg><p><strong>Oval</strong><br>Start / Ende</p></div><div><svg viewBox="0 0 140 70" aria-hidden="true"><path d="M25 10 H130 L115 60 H10 Z" fill="#eef6f3" stroke="#44776c" stroke-width="2"/></svg><p><strong>Parallelogramm</strong><br>Ein- / Ausgabe</p></div><div><svg viewBox="0 0 140 70" aria-hidden="true"><rect x="10" y="10" width="120" height="50" fill="#eef6f3" stroke="#44776c" stroke-width="2"/></svg><p><strong>Rechteck</strong><br>Verarbeitung</p></div><div><svg viewBox="0 0 140 70" aria-hidden="true"><path d="M70 5 L135 35 L70 65 L5 35 Z" fill="#eef6f3" stroke="#44776c" stroke-width="2"/></svg><p><strong>Raute</strong><br>Entscheidung</p></div></div><p>Pfeile legen die Reihenfolge fest. Aus einer Entscheidung führen zwei beschriftete Wege heraus: ja / nein bzw. true / false. Ein Rückpfeil kann eine Wiederholung bilden.</p>
    ${experiment('Vervollständigen Sie den Verdopplungsplan', '<p>Die Variable zahl enthält die zu verdoppelnde Zahl. Die Zählvariable anzahl gibt an, wie viele Verdopplungen noch auszuführen sind. Solange anzahl positiv ist, soll der Ja-Zweig zahl verdoppeln und anzahl um 1 verringern. Bei 0 soll der Nein-Zweig zur Ausgabe führen. Ein- und Ausgabe werden als Dezimalzahlen gelesen. Wählen Sie die Bedingung und die beiden Java-Anweisungen.</p><div class="slot-grid"><label for="pap-choice-condition">Welche Bedingung soll in der Raute geprüft werden?</label><select id="pap-choice-condition"><option value="">Bitte wählen</option><option>anzahl &gt; 0</option><option>anzahl == 0</option><option>zahl &gt; 0</option></select><label for="pap-choice-double">Welche Anweisung soll im ersten Rechteck zahl verdoppeln?</label><select id="pap-choice-double"><option value="">Bitte wählen</option><option>zahl = zahl * 2;</option><option>zahl = zahl + 1;</option></select><label for="pap-choice-decrement">Welche Anweisung soll im zweiten Rechteck die Zählvariable anzahl um 1 verringern?</label><select id="pap-choice-decrement"><option value="">Bitte wählen</option><option>anzahl = anzahl - 1;</option><option>anzahl = anzahl + 1;</option></select></div>'+pap+'<button id="pap-check" type="button">Plan prüfen</button><p id="pap-feedback" role="status"></p>')}
    <h3>Vom Plan zu Java</h3><p>Die Raute entspricht der Bedingung in ${inline('while (anzahl > 0)')}. Beide Rechtecke gehören in den Schleifenrumpf. ${inline('=')} weist einen Wert zu; ${inline('==')} vergleicht Werte.</p>`,
    reflection:'Zeichnen Sie selbst einen PAP für die Umrechnung mit Division durch 2. Wo werden die Reste gespeichert, und in welcher Reihenfolge müssen sie ausgegeben werden?',
    questions:[
      q('Elemente zuordnen','<p>Ordnen Sie die beiden beschriebenen Schritte den passenden Grundelementen eines Programmablaufplans (PAP) zu.</p>',[choice('decision','Welches PAP-Element verwenden Sie für eine Bedingung, deren Ergebnis ja oder nein ist?','diamond',[['rect','Rechteck'],['diamond','Raute'],['oval','Oval']]),choice('input','Welches PAP-Element verwenden Sie, um zwei Zahlen einlesen zu lassen?','parallelogram',[['rect','Rechteck'],['parallelogram','Parallelogramm'],['diamond','Raute']])],'Eine Entscheidung verzweigt. Ein- und Ausgabe haben eine eigene Form.','Raute: Entscheidung. Parallelogramm: Ein- oder Ausgabe. Rechteck: Verarbeitung. Oval: Start oder Ende.'),
      q('Die Bedingung ergänzen','<p>Die int-Variable zahl enthält die zu verdoppelnde Zahl. Die int-Zählvariable anzahl gibt die noch auszuführenden Verdopplungen an und wird nach jedem Durchlauf um 1 verringert. Verwenden Sie in der Bedingung ausdrücklich die Zählvariable <strong>anzahl</strong>. Tragen Sie eine Java-Bedingung für die Raute ein: Bei mindestens einer übrigen Verdopplung führt der Ja-Zweig zum Schleifenrumpf, bei 0 der Nein-Zweig zur Ausgabe. Schreiben Sie nur die Bedingung, ohne Klammern oder Semikolon.</p>',[java('condition','Welche Java-Bedingung mit der Zählvariable anzahl gehört in die Raute? Schreiben Sie nur die Bedingung.',['anzahl > 0','0 < anzahl','anzahl >= 1','1 <= anzahl'])],'Prüfen Sie, ob die Zählvariable positiv ist.','anzahl > 0 liefert genau dann true, wenn mindestens eine Wiederholung übrig ist.'),
      q('Verarbeitung formulieren','<p>Gegeben sind zwei bereits deklarierte int-Variablen: zahl enthält die zu verdoppelnde Zahl; die Zählvariable anzahl enthält die Anzahl der noch übrigen Verdopplungen. Ergänzen Sie die Berechnungen für <code>zahl = …;</code> und <code>anzahl = …;</code>: Verdoppeln Sie zahl und verringern Sie anzahl um 1. Sie können jeweils nur den Ausdruck rechts vom Gleichheitszeichen oder die vollständige Java-Anweisung mit Semikolon eingeben.</p>',[java('double','Wie berechnen Sie den neuen Wert von zahl, sodass er doppelt so groß ist? Geben Sie einen Ausdruck oder eine vollständige Anweisung ein.',['zahl = zahl * 2;','zahl *= 2;','zahl = 2 * zahl;','zahl = zahl + zahl;','zahl * 2','2 * zahl','zahl + zahl']),java('decrement','Wie berechnen Sie den neuen Wert von anzahl, sodass er um 1 kleiner ist? Geben Sie einen Ausdruck oder eine vollständige Anweisung ein.',['anzahl = anzahl - 1;','anzahl = -1 + anzahl;','anzahl = anzahl + -1;','anzahl--;','--anzahl;','anzahl -= 1;','anzahl - 1','-1 + anzahl','anzahl + -1'])],'Links steht die Variable, rechts der neu berechnete Wert.','Zum Beispiel zahl = 2 * zahl; und anzahl = -1 + anzahl;. Auch zahl * 2 bzw. anzahl - 1 berechnen dieselben neuen Werte. Sie können die Ausdrücke allein oder die vollständigen Anweisungen eingeben.'),
      q('Einen Fehler erkennen','<p>Der folgende Java-Code soll die Zahl 5₁₀ genau dreimal verdoppeln und dann ausgeben. Die Zählvariable anzahl wird jedoch versehentlich erhöht. Erklären Sie den Fehler.</p>'+code('int zahl = 5;\nint anzahl = 3;\nwhile (anzahl > 0) {\n    zahl = zahl * 2;\n    anzahl = anzahl + 1;\n}\nSystem.out.println(zahl);'),[choice('problem','Warum führt das Erhöhen von anzahl dazu, dass der beabsichtigte Schleifenabbruch nicht erreicht wird?','away',[['away','Die Zählvariable bewegt sich vom Abbruchwert 0 weg; der beabsichtigte Abbruch wird nicht erreicht.'],['once','Die Schleife läuft genau einmal.'],['nothing','Nur die Binärdarstellung ändert sich.']])],'Betrachten Sie die Folge 3, 4, 5, … statt 3, 2, 1, 0.','Die Zählvariable muss abnehmen. Im mathematischen Modell bleibt sie sonst positiv; Java-int läuft nach sehr vielen Schritten über. Dieser Überlauf ist kein sinnvoller Schleifenabbruch.')]
  },
  {
    id:'typen', name:'Datentypen', time:'15–20', title:'Werte und Referenzen auseinanderhalten.',
    intro:'Der Typ bestimmt, welche Werte eine Variable aufnehmen kann und welche Operationen zulässig sind.',
    lesson:`<aside class="rule" aria-labelledby="double-hinweis"><h3 id="double-hinweis">Zusatzhinweis: Normalerweise double benutzen</h3><p>Verwenden Sie für Kommazahlen normalerweise <strong>double</strong>. Das ist in Java der Standardtyp für Gleitkommaliterale wie ${inline('1.5')} und bietet mehr Genauigkeit als float.</p>${code('double speed = 1.5; // übliche Schreibweise\nfloat speedFloat = 1.5f; // float benötigt hier das f')}
    <p>Warum funktioniert ${inline('float speed = 1.5;')} nicht? Rechts steht ein double-Literal, links eine float-Variable. Java erlaubt diese Verkleinerung des Typs nicht automatisch, weil dabei Genauigkeit verloren gehen kann. Deshalb meldet der Compiler einen Fehler – auch bei 1.5, obwohl dieser einzelne Wert exakt als float darstellbar ist.</p><p>Das Suffix ${inline('f')} macht aus ${inline('1.5f')} ein float-Literal. Alternativ wäre eine ausdrückliche Typumwandlung wie ${inline('float speed = (float) 1.5;')} möglich. Für die üblichen Aufgaben bleiben Sie bei ${inline('double speed = 1.5;')}.</p></aside>
    <h3>Java hat acht primitive Datentypen.</h3><div class="table-wrap"><table class="type-table"><caption>Primitive Datentypen in Java</caption><thead><tr><th>Typ</th><th>Werte / Größe</th><th>Java-Beispiel</th></tr></thead><tbody><tr><td>boolean</td><td>true oder false; logische Information: 1 Bit, tatsächliche Speichergröße nicht festgelegt</td><td>${inline('boolean alive = true;')}</td></tr><tr><td>byte / short / int / long</td><td>Ganze Zahlen, 8 / 16 / 32 / 64 Bit, vorzeichenbehaftet</td><td>${inline('int size = 3;')}<br>${inline('long count = 3000000000L;')}</td></tr><tr><td>float / double</td><td>Gleitkommazahlen, 32 / 64 Bit, viele Dezimalwerte nur näherungsweise darstellbar</td><td>${inline('float speed = 1.5f;')}<br>${inline('double distance = 1.5;')}</td></tr><tr><td>char</td><td>16-Bit-UTF-16-Codeeinheit, nicht immer ein vollständiges Unicode-Zeichen</td><td>${inline("char symbol = 'B';")}</td></tr></tbody></table></div><h3>Komplexe Datentypen sind Referenztypen.</h3><p>Klassen wie ${inline('String')}, ${inline('Cell')} und ${inline('Field')} sind Referenztypen, ebenso Arrays. Eine entsprechende Variable enthält eine Referenz auf ein Objekt oder ${inline('null')}. Das Objekt selbst ist nicht in der Variablen enthalten.</p>${code('String name = "Ada"; // String mit großem S\nCell cell = new Cell(true);\nint[] values = new int[3];')}
    <p>Primitive Werte besitzen keine aufrufbaren Methoden. Über eine Objekt-Referenz können Sie Methoden aufrufen, z. B. ${inline('cell.change();')}. ${inline('void')} ist kein Variablentyp, sondern bezeichnet bei einer Methode „kein Rückgabewert“. Objekte werden oft mit ${inline('new')} erzeugt; ein Stringliteral ist ein wichtiger Sonderfall, der kein ausgeschriebenes ${inline('new')} benötigt.</p>
    ${experiment('Typdetektiv', '<label for="type-example">Java-Deklaration untersuchen</label><select id="type-example"><option value="boolean">boolean alive = true;</option><option value="int">int size = 3;</option><option value="float">float speed = 1.5f;</option><option value="String">String name = "Ada";</option><option value="Cell">Cell cell = new Cell(true);</option><option value="array">int[] values = new int[3];</option></select><div id="type-readout" class="readout" aria-live="polite"></div>')}`,
    reflection:'Vergleichen Sie int und Cell anhand von Inhalt der Variablen, Erzeugung und Methodenaufrufen. Warum ist String trotz seiner häufigen Verwendung kein primitiver Typ?',
    questions:[
      q('Typen unterscheiden','<p>Cell ist eine selbst definierte Klasse. Ordnen Sie die folgenden Java-Typen als primitiv oder als Referenztyp ein.</p>',[choice('boolean','Ist boolean in Java ein primitiver Datentyp oder ein Referenztyp?','primitive',kinds),choice('int','Ist int in Java ein primitiver Datentyp oder ein Referenztyp?','primitive',kinds),choice('String','Ist String in Java ein primitiver Datentyp oder ein Referenztyp?','reference',kinds),choice('Cell','Ist die selbst definierte Klasse Cell ein primitiver Datentyp oder ein Referenztyp?','reference',kinds)],'Java kennt nur acht primitive Typen; Klassennamen gehören nicht dazu.','boolean und int sind primitiv. String und Cell sind Klassen und damit Referenztypen.'),
      q('Literale richtig schreiben','<p>Wählen Sie für jede der beiden Variablenarten die syntaktisch gültige Java-Deklaration aus. Achten Sie auf den Datentyp, die Schreibweise des Literals und die Groß- und Kleinschreibung.</p>',[choice('float','Welche der folgenden Java-Anweisungen deklariert und initialisiert eine float-Variable korrekt?','f',[['f','float speed = 1.5f;'],['wrong','float speed = 1.5;'],['comma','float speed = 1,5;']]),choice('string','Welche der folgenden Java-Anweisungen deklariert und initialisiert eine String-Variable korrekt?','S',[['s','string name = "Ada";'],['S','String name = "Ada";'],['char',"String name = 'Ada';"]])],'Ein Dezimalliteral ohne Suffix ist double. Java unterscheidet Groß- und Kleinschreibung.','float benötigt hier das Suffix f. String beginnt groß und Zeichenketten stehen in doppelten Anführungszeichen.'),
      q('Der Inhalt einer Variable','<p>Gegeben: <code>int size = 3;</code> und <code>Field field = new Field(size);</code>. Field sei als Klasse mit passendem Konstruktor vorhanden.</p>',[choice('size','Was wird nach der Deklaration int size = 3; in der Variable size gespeichert?','value',[['value','Den primitiven Wert 3.'],['ref','Eine Referenz auf ein Objekt.']]),choice('field','Was wird nach der Anweisung Field field = new Field(size); in der Variable field gespeichert?','ref',[['value','Direkt alle Zellen des Spielfelds.'],['ref','Eine Referenz auf das erzeugte Field-Objekt.']])],'Trennen Sie das Objekt und die Variable, die auf dieses Objekt verweist.','size enthält 3 direkt. field enthält eine Referenz, über die das Field-Objekt erreichbar ist.'),
      q('Typfehler begründen','<p>Field ist eine Klasse mit dem Konstruktor <code>Field(int size)</code>. Die Anweisung <code>Field field = 3;</code> soll ein neues Spielfeld der Größe 3 erzeugen, ist aber ungültig. Begründen Sie den Typfehler und schreiben Sie die korrigierte Deklaration mit Objekt-Erzeugung.</p>',[choice('reason','Warum darf der Variable field vom Typ Field nicht einfach der Wert 3 zugewiesen werden?','mismatch',[['mismatch','3 ist ein int-Wert und keine zu Field passende Referenz.'],['name','Variablennamen dürfen nicht field heißen.'],['new','Jede Java-Variable muss mit new erzeugt werden.']]),java('fix','Wie lautet die vollständige Java-Anweisung, die eine Variable field deklariert und ein neues Field-Objekt mit der Größe 3 erzeugt?','Field field = new Field(3);')],'Der Typ links muss zum Ergebnis des Ausdrucks rechts passen.','Field field = new Field(3); erzeugt ein Objekt und speichert die passende Referenz. Primitive Variablen brauchen kein new.')]
  },
  {
    id:'variablen', name:'Variablen erstellen', time:'15–20', title:'Ein Name bekommt einen Typ und einen Wert.',
    intro:'Unterscheiden Sie Deklaration, Initialisierung und spätere Zuweisung – im Java-Code und im vereinfachten Rechnermodell.',
    lesson:`<h3>Deklaration ist noch keine Wertzuweisung.</h3>${code('int size;       // Deklaration: Typ und Name\nsize = 3;       // erste Zuweisung: Initialisierung\nsize = size + 1; // spätere Zuweisung, danach 4\n\nboolean alive = true; // Deklaration + Initialisierung')}
    <p>Die Form lautet <strong>Typ Name = Ausdruck;</strong>. Der Ausdruck rechts wird zuerst ausgewertet; sein Wert ersetzt dann den bisherigen Inhalt der linken Variable. ${inline('size = size + 1;')} ist deshalb keine mathematische Gleichung.</p><p>Lokale Variablen müssen vor dem Lesen sicher initialisiert sein. Attribute eines Objekts erhalten dagegen Standardwerte, etwa 0, false oder null, falls sie nicht ausdrücklich initialisiert werden. Java-Bezeichner sind groß-/kleinschreibungsabhängig; sie dürfen nicht mit einer Ziffer beginnen und keine Schlüsselwörter sein.</p>
    ${experiment('Vom Code zum Speicherzustand', '<p>Führen Sie die Anweisungen einzeln aus. „Nicht initialisiert“ ist kein Java-Wert und darf nicht gelesen werden.</p><div id="variable-code"></div><div class="controls"><button type="button" id="variable-step">Nächste Anweisung</button><button type="button" id="variable-reset" class="secondary">Zurücksetzen</button></div><div id="variable-memory" class="readout" aria-live="polite"></div>')}
    <p class="memory-note">Das Modell zeigt benannte Variablenfelder. Es behauptet nicht, dass jede Java-Variable an einem festen physischen Speicherplatz liegt.</p>`,
    reflection:'Beschreiben Sie für int size = 3; die drei Entscheidungen Typ, Name und Anfangswert. Was unterscheidet die Zuweisung size = size + 1; von einer mathematischen Gleichung?',
    questions:[
      q('Eine Variable deklarieren','<p>Schreiben Sie eine vollständige Java-Deklaration: int-Variable size mit Anfangswert 3.</p>',[java('code','Wie lautet die vollständige Java-Anweisung, die eine int-Variable size mit dem Anfangswert 3 deklariert?','int size = 3;')],'Typ zuerst, dann Name, Zuweisung und Semikolon.','int size = 3; deklariert size als int und initialisiert die Variable mit 3.'),
      q('Eine boolesche Variable','<p>Erstellen Sie eine boolean-Variable alive und initialisieren Sie sie mit false.</p>',[java('code','Wie lautet die vollständige Java-Anweisung, die eine boolean-Variable alive mit dem Anfangswert false deklariert?','boolean alive = false;')],'Die booleschen Literale true und false werden kleingeschrieben.','boolean alive = false; enthält einen primitiven booleschen Wert und benötigt kein new.'),
      q('Zuweisungen verfolgen','<p>Führen Sie ausschließlich die folgenden drei Anweisungen aus. Welche Werte haben x und y danach? Geben Sie beide als Dezimalzahlen ein.</p>'+code('int x = 5;\nint y = x;\ny = 7;'),[number('x','Welchen Wert hat die Variable x, nachdem alle drei Anweisungen ausgeführt wurden?',5),number('y','Welchen Wert hat die Variable y, nachdem alle drei Anweisungen ausgeführt wurden?',7),choice('copy','Was wird von x nach y kopiert, wenn die Anweisung int y = x; ausgeführt wird?','value',[['value','Der primitive Wert 5.'],['link','Eine dauerhafte Verbindung zwischen x und y.']])],'Das Kopieren eines primitiven Werts koppelt die Variablen nicht.','Nach dem Kopieren sind x und y unabhängig. Nur y wird auf 7 gesetzt; x bleibt 5.'),
      q('Vor dem Lesen initialisieren','<p>Die folgenden Anweisungen stehen innerhalb einer Java-Methode. count ist eine lokale Variable und wird vorher nicht initialisiert. Was geschieht?</p>'+code('int count;\nSystem.out.println(count);'),[choice('result','Was passiert beim Kompilieren, wenn die angegebene lokale Variable count vor der Ausgabe keinen Wert zugewiesen bekommt?','compile',[['zero','Es wird automatisch 0 ausgegeben.'],['compile','Compilerfehler: Die lokale Variable ist nicht initialisiert.'],['null','Es wird null ausgegeben.']])],'Unterscheiden Sie lokale Variablen und Objektattribute.','Lokale Variablen bekommen keinen automatisch lesbaren Standardwert. Vor der Ausgabe muss z. B. count = 0; ausgeführt werden.')]
  },
  {
    id:'information', name:'Informationsgehalt', time:'15–20', title:'Wie viele Möglichkeiten stecken in n Bits?',
    intro:'Zählen Sie unterscheidbare Zustände und bestimmen Sie die nötige Bitanzahl. Bedeutung und Speicherbedarf sind verschiedene Fragen.',
    lesson:`<h3>n Bits ermöglichen 2ⁿ Muster.</h3><p>Ein Bit unterscheidet zwei Zustände, zwei Bits vier, drei Bits acht. Für N unterscheidbare Möglichkeiten benötigen Sie mindestens ${inline('ceil(log₂(N))')} Bits: die kleinste ganze Bitanzahl, für die 2ⁿ ≥ N gilt.</p><p class="rule">8 Bits → 256 Muster<br>10 gleichwahrscheinliche Zustände → log₂(10) ≈ 3,32 Bit Information → mindestens 4 Bits für eine feste Binärcodierung</p><p>Bei N gleichwahrscheinlichen Möglichkeiten beschreibt log₂(N) den Informationsgehalt der Auswahl. Die feste Codebreite wird aufgerundet. Der tatsächliche Speicherbedarf kann größer sein: Ein Java-int nutzt 32 Bit, auch wenn Sie nur Werte von 0 bis 9 einsetzen. Ein boolean trägt logisch höchstens 1 Bit Information; seine konkrete Speicherbelegung ist nicht allgemein festgelegt.</p><p>Ein int hat 2³² unterschiedliche Bitmuster, als Zahlen −2³¹ bis 2³¹ − 1. char hat 2¹⁶ mögliche UTF-16-Codeeinheiten. Eine String-Variable verweist auf ein Objekt; Textlänge und Speicherbedarf sind nicht pauschal ein fester Bitwert.</p>
    ${experiment('Codierlabor', '<label for="info-bits">Codebreite: <output id="info-bits-label"></output></label><input id="info-bits" type="range" min="1" max="16" value="8"><p id="info-capacity" class="count-display" aria-live="polite"></p><label for="info-states">Benötigte Zustände als Dezimalzahl (1–65536)</label><input id="info-states" type="number" min="1" max="65536" step="1" value="10"><div id="info-result" class="readout" aria-live="polite"></div>')}
    <h3>Muster sind noch keine Bedeutung.</h3><p>Der Zahlenwert 66, das ASCII-Zeichen B und die LEDs 2 und 7 können dasselbe Muster nutzen. Typ, Codierung und Programmlogik entscheiden, welche Information Sie daraus lesen.</p>`,
    reflection:'Eine Ampel hat drei Zustände. Begründen Sie, weshalb zwei Bits genügen, aber ein Muster ungenutzt bleibt. Warum ist damit noch nicht die tatsächliche Speichergröße eines Java-Objekts bekannt?',
    questions:[
      q('Möglichkeiten zählen','<p>Verwenden Sie sechs Bits, um nicht negative ganze Zahlen darzustellen. Das Muster 000000₂ steht für die Zahl 0. Bestimmen Sie, wie viele verschiedene Muster insgesamt möglich sind und welchen Zahlenwert das größte Muster hat.</p>',[number('patterns','Wie viele verschiedene Bitmuster können Sie mit sechs Bits bilden?',64),number('max','Welche ist die größte nicht negative ganze Zahl, die sich mit sechs Bits darstellen lässt?',63)],'Die Anzahl ist eine Zweierpotenz. Die Zahl 0 gehört zum Wertebereich.','2⁶ = 64 Muster, von 000000₂ = 0 bis 111111₂ = 63.'),
      q('Minimale Codebreite','<p>Für die zehn Ziffern 0 bis 9 soll jeweils ein eigenes binäres Codewort verwendet werden. Alle Codewörter sollen gleich lang sein. Bestimmen Sie die kleinste ausreichende Bitanzahl und zählen Sie, wie viele Muster bei dieser Codebreite nicht für eine Ziffer gebraucht werden.</p>',[number('bits','Wie viele Bits benötigen Sie mindestens pro Codewort, um die zehn Ziffern 0 bis 9 eindeutig zu unterscheiden?',4),number('unused','Wie viele Bitmuster bleiben bei dieser kleinsten möglichen Codebreite ungenutzt?',6)],'Drei Bits reichen für acht Zustände; prüfen Sie die nächste Breite.','2³ = 8 reicht nicht; 2⁴ = 16 reicht. Es bleiben 16 − 10 = 6 ungenutzte Muster.'),
      q('Logische Information und Java-Speicher','<p>Betrachten Sie die Deklarationen <code>boolean alive = true;</code> und <code>int size = 3;</code>. Unterscheiden Sie die logisch nötige Information zum Unterscheiden der Werte von der im Java-Datentyp festgelegten Bitbreite bzw. der tatsächlichen Speicherbelegung.</p>',[number('boolean','Wie viele Bits benötigen Sie mindestens, um die beiden boolean-Werte true und false zu unterscheiden?',1),number('int','Wie viele Bit belegt der Wert einer Variable vom primitiven Java-Typ int im Speicher?',32),choice('storage','Kann man aus den zwei möglichen boolean-Werten ableiten, wie viel Speicher eine boolean-Variable auf jeder JVM tatsächlich belegt?','unspecified',[['one','Ein boolean belegt auf jeder JVM genau ein Bit im Speicher.'],['unspecified','Die zwei Zustände legen die konkrete Speicherbelegung nicht fest.']])],'Zwei Zustände tragen 1 Bit Information. Die Implementierung der Speicherung ist eine andere Ebene.','boolean unterscheidet zwei Werte, entsprechend 1 Bit logischer Information. Java legt seine konkrete Speichergröße nicht allgemein fest; int hat eine definierte Breite von 32 Bit.'),
      q('Zustände und Bedeutung','<p>Eine Ampel hat die drei Zustände Rot, Gelb und Grün. Das Programm verwendet dafür die binären Codewörter 00, 01 und 10; 01 ist dabei als Gelb vereinbart. Bestimmen Sie die Länge der Codewörter und die Anzahl ungenutzter Muster. Überlegen Sie außerdem, woher die Bedeutung der Bitmuster kommt.</p>',[number('bits','Wie viele Bits enthält jedes der angegebenen Codewörter für einen Ampelzustand?',2),number('unused','Wie viele der möglichen Codewörter bleiben bei der Codierung dieser drei Ampelzustände ungenutzt?',1),choice('meaning','Wodurch wird festgelegt, dass das Codewort 01 für die Ampelfarbe Gelb steht?','program',[['bits','Das Bitmuster selbst.'],['program','Die vereinbarte Codierung im Programm.']])],'Zwei Bits liefern vier Muster. Die Bedeutung muss vereinbart sein.','00, 01, 10 und 11 sind vier Muster. Drei sind belegt. Die Zuordnung zu Farben stammt aus der Codierung, nicht aus den Bits.')]
  },
  {
    id:'klassen', name:'Klassendiagramme', time:'20–25', title:'Vom Bauplan zum Klassendiagramm.',
    intro:'Lesen Sie Attribute, Konstruktoren und Methoden der Klasse Cell und übertragen Sie sie in die drei Bereiche eines Diagramms.',
    lesson:`<h3>Die Klasse beschreibt gemeinsame Eigenschaften.</h3><p>Eine Klasse ist ein Bauplan für Objekte. Sie definiert Attribute und Methoden. Ein Konstruktor initialisiert ein neu erzeugtes Objekt. Er heißt wie die Klasse und besitzt <strong>keinen Rückgabetyp</strong>, auch kein void.</p>${code(cell)}
    <p>Im Diagramm der Klausurübung wird Java-Schreibweise verwendet: Datentyp vor Attributname, Rückgabetyp vor Methodenname. Sichtbarkeit kann ergänzend angegeben werden. In klassischer UML findet man auch ${inline('alive: boolean')}; hier bleiben wir bei Java.</p><div class="uml" aria-label="Klassendiagramm Cell in Java-Schreibweise"><div class="class-name">Cell</div><div>${inline('private boolean alive')}</div><div>${inline('Cell(boolean alive)')}${inline('boolean getAlive()')}${inline('void setAlive(boolean alive)')}${inline('void change()')}</div></div><p>Das Attribut ist private. Die übrigen hier nicht mit public/private markierten Elemente haben Paketsichtbarkeit. ${inline('this.alive = alive;')} weist dem Attribut den Parameterwert zu. ${inline('!')} kehrt einen booleschen Wert um.</p>
    ${experiment('Diagramm-Bausteine einordnen', '<label for="class-part">Java-Baustein</label><select id="class-part"><option value="class">class Cell</option><option value="attribute">private boolean alive;</option><option value="constructor">Cell(boolean alive)</option><option value="getter">boolean getAlive()</option><option value="setter">void setAlive(boolean alive)</option><option value="change">void change()</option></select><div id="class-readout" class="readout" aria-live="polite"></div>')}`,
    reflection:'Skizzieren Sie das gesamte Klassendiagramm von Cell aus dem Gedächtnis. Begründen Sie, warum void Cell(boolean alive) kein Konstruktor wäre.',
    questions:[
      q('Die Bereiche zuordnen','<p>Ordnen Sie die Elemente den Bereichen des Klassendiagramms zu.</p>',[choice('name','In welchem Bereich des Klassendiagramms steht der Klassenname Cell?','top',[['top','Oberes Feld: Klassenname'],['middle','Mittleres Feld: Attribute'],['bottom','Unteres Feld: Konstruktor und Methoden']]),choice('attribute','In welchem Bereich des Klassendiagramms steht das Attribut boolean alive?','middle',[['top','Oberes Feld: Klassenname'],['middle','Mittleres Feld: Attribute'],['bottom','Unteres Feld: Konstruktor und Methoden']]),choice('method','In welchem Bereich des Klassendiagramms steht die Methode void change()?','bottom',[['top','Oberes Feld: Klassenname'],['middle','Mittleres Feld: Attribute'],['bottom','Unteres Feld: Konstruktor und Methoden']])],'Ein Diagramm trennt Name, gespeicherten Zustand und Verhalten.','Oben steht Cell, in der Mitte boolean alive, unten der Konstruktor und die Methoden.'),
      q('Den Konstruktor notieren','<p>Schreiben Sie nur die Signatur des Konstruktors der Klasse Cell mit einem boolean-Parameter alive. Kein Methodenrumpf und kein Semikolon.</p>',[java('constructor','Wie lautet die Signatur des Cell-Konstruktors mit dem boolean-Parameter alive? Lassen Sie Rumpf und Semikolon weg.','Cell(boolean alive)')],'Ein Konstruktor heißt wie die Klasse und hat keinen Rückgabetyp.','Cell(boolean alive) ist die Signatur. Mit void davor wäre es eine Methode statt des Konstruktors.'),
      q('Methoden unterscheiden','<p>Lesen Sie die folgende Klasse Cell. Geben Sie die Signatur der Methode an, die alive zurückgibt, und die Signatur der Methode, die einen neuen Wert als Parameter übernimmt. Schreiben Sie jeweils nur die Signatur in Java-Schreibweise, ohne Rumpf oder Semikolon.</p>'+code(cell),[java('getter','Wie lautet die Signatur der Methode, die den aktuellen Wert von alive zurückgibt? Lassen Sie Rumpf und Semikolon weg.','boolean getAlive()'),java('setter','Wie lautet die Signatur der Methode, die einen neuen boolean-Wert übernimmt und in alive speichert? Lassen Sie Rumpf und Semikolon weg.','void setAlive(boolean alive)')],'Der Getter liefert einen boolean; der Setter übernimmt einen Parameter und liefert nichts zurück.','boolean getAlive() liefert den Zustand. void setAlive(boolean alive) übernimmt den neuen Zustand und hat keinen Rückgabewert.'),
      q('Eine Methode verstehen',cellContext+'<p>Ein Cell-Objekt hat zu Beginn den Zustand <code>alive = true</code>. Auf diesem Objekt wird die folgende Methode <code>change()</code> genau einmal aufgerufen. Bestimmen Sie den Zustand danach und wählen Sie die passende Erklärung.</p>'+code('void change() {\n    setAlive(!getAlive());\n}'),[choice('value','Welchen Wert hat das Attribut alive nach einem Aufruf von change(), wenn es davor true war?','false',truth),choice('reason','Welche Beschreibung erklärt, wie change() den gespeicherten Zustand verändert?','not',[['not','! negiert den gelesenen Wert und der Setter speichert ihn.'],['new','change() erzeugt immer ein neues Cell-Objekt.'],['print','Die Methode gibt nur den Wert aus.']])],'Das Zeichen ! ist die logische Negation.','getAlive() liefert true; !true ergibt false. setAlive(false) speichert false im selben Objekt.')]
  },
  {
    id:'objekte', name:'Objekte & Referenzen', time:'20–25', title:'Zwei Variablen sind nicht immer zwei Objekte.',
    intro:'Verfolgen Sie Instanziierung, das Kopieren von Referenzen und unabhängige Objektzustände im Rechnermodell.',
    lesson:`<h3>Drei Schritte in einer Anweisung</h3>${code('Cell a = new Cell(true);')}
    <ol><li>${inline('Cell a')} deklariert eine Variable vom Typ Cell.</li><li>${inline('new Cell(true)')} erzeugt eine neue Instanz; der Konstruktor setzt alive auf true.</li><li>Die Zuweisung speichert die Referenz auf diese Instanz in a.</li></ol><p>${inline('Cell b = a;')} kopiert die Referenz, nicht das Objekt. Beide Variablen erreichen nun dasselbe Objekt. Dagegen erzeugt jedes ${inline('new Cell(true)')} eine eigene Instanz.</p>${code('int size = 3;\nField field = new Field(size); // Field mit passendem Konstruktor vorausgesetzt\nCell empty = null;            // Referenzvariable ohne Objekt')}
    <p>${inline('Cell a;')} allein erzeugt noch kein Objekt. ${inline('null')} bedeutet „keine Referenz auf ein Objekt“; ein Aufruf wie ${inline('empty.change();')} löst dann eine NullPointerException aus.</p>
    ${experiment('Wertkopie oder Referenzkopie?', '<label for="object-mode">Szenario</label><select id="object-mode"><option value="alias">Referenz kopieren: Cell b = a;</option><option value="independent">Zweites Objekt: Cell b = new Cell(true);</option><option value="primitive">Primitive Werte: int y = x;</option></select><div id="object-code"></div><div class="controls"><button type="button" id="object-step">Nächste Anweisung</button><button type="button" id="object-reset" class="secondary">Zurücksetzen</button></div><div id="object-memory" class="memory-grid" aria-live="polite"></div><p class="memory-note">Objekt #1 und #2 sind Modellnamen, keine echten Speicheradressen. Ein Pfeil → stellt eine Referenz dar.</p>')}`,
    reflection:'Erklären Sie am Beispiel Cell b = a; und Cell b = new Cell(true); den Unterschied zwischen Referenzkopie und Instanziierung. Vergleichen Sie dies mit int y = x;.',
    questions:[
      q('Unabhängige Objekte',cellContext+code('Cell a = new Cell(true);\nCell b = new Cell(true);\na.change();'),[choice('a','Welchen Wert liefert a.getAlive(), nachdem alle angegebenen Anweisungen ausgeführt wurden?','false',truth),choice('b','Welchen Wert liefert b.getAlive(), nachdem alle angegebenen Anweisungen ausgeführt wurden?','true',truth),number('count','Wie viele neue Cell-Objekte werden durch die angegebenen Anweisungen insgesamt erzeugt?',2)],'Zählen Sie new. Jede Instanz hat ihren eigenen alive-Wert.','Zwei new-Ausdrücke erzeugen zwei Objekte. a wird auf false umgeschaltet, b bleibt true.'),
      q('Gemeinsames Objekt',cellContext+code('Cell a = new Cell(true);\nCell b = a;\nb.change();'),[choice('a','Welchen Wert liefert a.getAlive(), nachdem alle angegebenen Anweisungen ausgeführt wurden?','false',truth),choice('b','Welchen Wert liefert b.getAlive(), nachdem alle angegebenen Anweisungen ausgeführt wurden?','false',truth),number('count','Wie viele neue Cell-Objekte werden durch die angegebenen Anweisungen insgesamt erzeugt?',1)],'Es gibt nur einen new-Ausdruck. Beide Referenzen erreichen dieselbe Instanz.','b = a kopiert die Referenz. b.change() verändert das gemeinsame Objekt; beide Getter liefern false.'),
      q('Syntax der Instanziierung','<p>Die Klasse Cell besitzt den Konstruktor <code>Cell(boolean alive)</code>, der den Anfangszustand übernimmt. Erzeugen Sie innerhalb einer Methode mit Zugriff auf diesen Konstruktor eine neue Cell-Instanz mit alive = false. Deklarieren Sie dafür eine neue Variable c und speichern Sie darin die Referenz. Schreiben Sie die vollständige Java-Anweisung mit Semikolon.</p>',[java('code','Wie lautet die vollständige Java-Anweisung, die eine Variable c vom Typ Cell deklariert und ihr eine neue Cell-Instanz mit dem Anfangszustand false zuweist?','Cell c = new Cell(false);')],'Der Klassentyp steht vor dem Variablennamen. Rechts steht new mit Konstruktoraufruf.','Cell c = new Cell(false); deklariert c, erzeugt eine neue Instanz und speichert deren Referenz.'),
      q('Deklaration ist keine Instanz','<p>Cell ist eine Klasse mit der Instanzmethode <code>void change()</code>. Betrachten Sie nur die folgenden beiden lokalen Variablendeklarationen in einer Methode. Wie viele Objekte erzeugen diese Zeilen, und was würde ein anschließender Aufruf <code>b.change();</code> bewirken?</p>'+code('Cell a;\nCell b = null;'),[number('objects','Wie viele Cell-Objekte werden allein durch die beiden angegebenen Variablendeklarationen erzeugt?',0),choice('null','Was passiert, wenn Sie nach diesen Deklarationen die Anweisung b.change(); ausführen?','exception',[['false','b erhält automatisch den Zustand false.'],['exception','NullPointerException: b verweist auf kein Objekt.'],['new','Ein neues Objekt wird automatisch erzeugt.']])],'Ohne new wird hier kein Cell-Objekt erzeugt. null ist kein Objekt.','Beide Zeilen erzeugen nur Variablen, kein Cell-Objekt. a ist als lokale Variable noch nicht initialisiert; b enthält null, weshalb b.change() scheitert.')]
  },
  {
    id:'check', name:'Abschlusscheck', time:'25–35', title:'Alles zusammen: der Klausurcheck.',
    intro:'Lösen Sie die gemischten Aufgaben möglichst ohne Hilfe. Notieren Sie Ihre Begründungen, bevor Sie die Rückmeldung öffnen.',
    lesson:'<h3>Ihr Werkzeugkasten</h3><p>Stellenwerte addieren · Reste rückwärts lesen · Schleifen protokollieren · PAP-Elemente erkennen · Typen prüfen · Werte und Referenzen trennen · Zustände zählen · Klassendiagramme lesen.</p><p>Die acht Aufgaben prüfen die wichtigsten Aspekte der Klausurübung. Freie Begründungen werden nicht automatisch bewertet; vergleichen Sie diese selbst mit dem Lösungsweg.</p>',
    reflection:'Welche zwei Denkfehler haben Sie korrigiert? Begründen Sie schriftlich den Unterschied zwischen Klasse, Objekt und Referenzvariable und erklären Sie eine komplette Schleifenausführung.',
    questions:[
      q('Binärzahlen','<p>Wandeln Sie 101101₂ in eine Dezimalzahl und die Dezimalzahl 37₁₀ in eine achtstellige Binärzahl um.</p>',[number('decimal','Welche Dezimalzahl entspricht der Binärzahl 101101₂?',45),text('binary','Wie lautet die Binärzahl für die Dezimalzahl 37₁₀? Verwenden Sie genau acht Stellen.','00100101')],'Nutzen Sie die Stellenwerte 32, 16, 8, 4, 2 und 1.','101101₂ = 32 + 8 + 4 + 1 = 45. 37 = 32 + 4 + 1 = 00100101₂.'),
      q('Dateninhalt und Informationsgehalt','<p>Ein Byte enthält das Binärmuster 01000010₂. Deuten Sie es als positive ganze Zahl, als ASCII-Zeichen und als acht LED-Schaltzustände. ASCII: Die Dezimalzahlen 65 und 66 entsprechen A und B. Die LEDs sind von links mit 1 bis 8 nummeriert; eine 1 bedeutet „leuchtet“. Geben Sie den Zahlenwert und die Anzahl möglicher Muster als Dezimalzahlen an.</p>',[number('number','Welche Dezimalzahl stellt das Bitmuster 01000010₂ dar?',66),text('char','Welches ASCII-Zeichen wird durch dieses Bitmuster dargestellt?','B'),text('leds','Welche LEDs leuchten? Geben Sie ihre Nummern als Dezimalzahlen durch ein Komma getrennt ein, zum Beispiel 1,8.',['2,7','2 und 7','2 7']),number('states','Wie viele verschiedene Bitmuster sind bei einem Byte mit acht Bits insgesamt möglich?',256)],'Ein Muster lässt sich mit verschiedenen Codierungen lesen.','64 + 2 = 66, entsprechend ASCII B und den LEDs 2 und 7. Ein Byte besitzt 2⁸ = 256 Muster. Die Bedeutung kommt vom Programm bzw. Datentyp.'),
      q('Ein vollständiger Algorithmus','<p>Ein PAP beginnt mit zahl = 5 und anzahl = 3 (beides int-Variablen). Die Zählvariable anzahl gibt die übrigen Verdopplungen an. Vor jedem Durchlauf prüft die Raute, ob noch mindestens eine Verdopplung übrig ist. Bei ja wird zahl verdoppelt, anzahl um 1 verringert und zur Raute zurückgesprungen; bei nein wird zahl ausgegeben und beendet. Geben Sie die Java-Bedingung ohne Klammern oder Semikolon und den ausgegebenen Wert einmal als Dezimalzahl und einmal als Binärzahl mit acht Stellen an.</p>',[java('condition','Welche Java-Bedingung mit anzahl gehört in die Raute dieses PAP? Lassen Sie Klammern und Semikolon weg.','anzahl > 0'),number('result','Welche Dezimalzahl wird nach dem Ende der Schleife ausgegeben?',40),text('binary','Wie lautet dieselbe Ausgabe als Binärzahl mit genau acht Stellen?','00101000')],'Protokollieren Sie die Paare (zahl, anzahl) nach jedem Durchlauf.','Die Raute enthält anzahl > 0. (5,3) → (10,2) → (20,1) → (40,0). Ausgabe: 40 bzw. 00101000₂.'),
      q('Die Grenze begründen','<p>Beginnen Sie mit der Dezimalzahl 5₁₀ und verdoppeln Sie sie wiederholt. Jeder Schritt entspricht einer Linksverschiebung. Der größte zugelassene Wert ist 255₁₀. Geben Sie die maximal mögliche Anzahl der Verdopplungen als Dezimalzahl an und wählen Sie die passende Begründung.</p>',[number('times','Wie oft können Sie die Startzahl 5 höchstens verdoppeln, bevor das Ergebnis größer als 255 wird?',5),choice('why','Welche Begründung erklärt, weshalb danach eine weitere Verdopplung nicht mehr in acht Bits passt?','limit',[['limit','160 ≤ 255; der nächste Wert 320 überschreitet die 8-Bit-Grenze.'],['six','256 ist mit acht Bits noch darstellbar.'],['sign','Jede Linksverschiebung erzeugt automatisch eine negative Zahl.']])],'Der größte vorzeichenlose 8-Bit-Wert ist 255.','5 · 2⁵ = 160 passt, 5 · 2⁶ = 320 nicht. Jedes Bit rückt auf einen doppelt so großen Stellenwert.'),
      q('Typen und Variablen','<p>Field ist eine Klasse mit dem Konstruktor <code>Field(int size)</code>. Untersuchen Sie die beiden folgenden Deklarationen. Korrigieren Sie danach unabhängig davon die angegebene fehlerhafte Deklaration so, dass eine int-Variable size mit dem Anfangswert 3 entsteht.</p>'+code('int size = 3;\nField field = new Field(size);'),[choice('size','Was enthält die Variable size nach der angegebenen Deklaration?','value',[['value','Direkt der primitive Wert 3.'],['object','Ein Field-Objekt.']]),choice('field','Was enthält die Variable field nach der angegebenen Deklaration?','reference',[['reference','Eine Referenz auf ein Field-Objekt.'],['three','Direkt die Zahl 3.']]),java('fix','Wie korrigieren Sie die fehlerhafte Anweisung int size = new Field(3);, sodass size stattdessen den int-Wert 3 erhält?','int size = 3;')],'Vergleichen Sie den Typ links und das Ergebnis des Ausdrucks rechts.','size ist int und enthält 3. field ist ein Referenztyp und enthält einen Verweis. Die fehlerhafte int-Deklaration wird zu int size = 3;.'),
      q('Cell als Klassendiagramm','<p>Übertragen Sie die folgenden Bestandteile der unten vollständig angegebenen Klasse Cell in die Java-Schreibweise eines Klassendiagramms: Attribut, Konstruktor, Getter und Umschaltmethode. Schreiben Sie beim Attribut den Datentyp mit. Geben Sie bei Konstruktor und Methoden die vollständige Parameterliste mit Datentyp und Name jedes Parameters an; ohne Parameter schreiben Sie leere Klammern (). Schreiben Sie bei Methoden außerdem den Rückgabetyp mit, auch void, wenn kein Wert zurückgegeben wird. Der Konstruktor hat keinen Rückgabetyp. Lassen Sie die Sichtbarkeitsangabe des Attributs weg. Schreiben Sie weder Semikolon noch Methodenrumpf.</p>'+code(cell),[java('attribute','Wie lautet die Deklaration des Attributs in Java-Schreibweise? Lassen Sie Sichtbarkeitsangabe und Semikolon weg.','boolean alive'),java('constructor','Wie lautet die Signatur des Konstruktors der angegebenen Klasse Cell?','Cell(boolean alive)'),java('getter','Wie lautet die Signatur der Methode, die den Wert von alive zurückgibt?','boolean getAlive()'),java('change','Wie lautet die Signatur der Methode, die den Wert von alive umkehrt?','void change()')],'Der Konstruktor hat keinen Rückgabetyp; Getter und change() schon.','Attribut: boolean alive. Konstruktor: Cell(boolean alive). Methoden u. a. boolean getAlive() und void change(). Der Setter lautet void setAlive(boolean alive).'),
      q('Wertkopie und Referenzkopie',cellContext+code('int x = 5;\nint y = x;\ny = 7;\nCell a = new Cell(true);\nCell b = a;\nb.change();'),[number('x','Welchen Wert hat die Variable x nach der Ausführung des gesamten Codes?',5),number('y','Welchen Wert hat die Variable y nach der Ausführung des gesamten Codes?',7),choice('a','Welchen Wert liefert a.getAlive() nach der Ausführung des gesamten Codes?','false',truth),choice('b','Welchen Wert liefert b.getAlive() nach der Ausführung des gesamten Codes?','false',truth)],'Primitive Werte werden kopiert; bei Cell wird die Referenz kopiert.','x = 5, y = 7. Es existiert nur ein Cell-Objekt. a und b verweisen darauf, daher liefern beide Getter nach b.change() false.'),
      q('Ein Objekt selbst erstellen','<p>Cell ist eine Klasse mit dem Konstruktor <code>Cell(boolean alive)</code>. Erstellen Sie unabhängig von anderen Aufgaben eine boolean-Variable ready mit true und eine neue Cell-Instanz mit false in einer neu deklarierten Variable c. Die beiden vollständigen Java-Anweisungen mit Semikolon stehen in einer Methode mit Zugriff auf den Konstruktor. Zählen Sie nur die hier neu erzeugten Cell-Objekte; geben Sie die Anzahl als Dezimalzahl an.</p>',[java('primitive','Wie deklarieren und initialisieren Sie die primitive Variable ready mit dem boolean-Wert true? Schreiben Sie die vollständige Java-Anweisung.','boolean ready = true;'),java('object','Wie deklarieren Sie c vom Typ Cell und weisen ihr eine neu erzeugte Cell-Instanz mit dem Anfangszustand false zu? Schreiben Sie die vollständige Java-Anweisung.','Cell c = new Cell(false);'),number('count','Wie viele neue Cell-Objekte werden durch Ihre beiden Anweisungen insgesamt erzeugt?',1)],'Nur der new-Ausdruck erzeugt eine Instanz.','boolean ready = true; und Cell c = new Cell(false);. Eine primitive Variable entsteht ohne new, das Cell-Objekt durch den Konstruktoraufruf nach new.')]
  }
  ];
  return { stations, escape, code, cell };
})();
